mapper.select:
SELECT COUNT(*)
FROM ${table}
WHERE uploader_user_id = #{userId}

  AND meeting_id = #{meetingId}

SELECT
  doc_id, uploader_user_id, meeting_id,
  original_name, filepath, mime_type, size,
  sha256, original_lang, storage_key, uploaded_at
FROM ${table}
WHERE uploader_user_id = #{userId}

  AND meeting_id = #{meetingId}

ORDER BY uploaded_at DESC, doc_id DESC
LIMIT #{limit} OFFSET #{offset}

SELECT
  doc_id, uploader_user_id, meeting_id,
  original_name, filepath, mime_type, size,
  sha256, original_lang, storage_key, uploaded_at
FROM ${table}
WHERE doc_id = #{docId}
  AND uploader_user_id = #{userId}

